            {filtered.map(item => (
              <div key={item.id} style={{ background: '#070a12', border: '1px solid #1e293b', padding: '16px', borderRadius: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
